import{_ as t,o as a,c,a5 as n}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — List Agency (FR 3.4.1)","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-1-list-agency/plan.md","filePath":"feature/agency-workspace/3-4-1-list-agency/plan.md"}'),o={name:"feature/agency-workspace/3-4-1-list-agency/plan.md"};function d(i,e,r,s,l,h){return a(),c("div",null,[...e[0]||(e[0]=[n(`<h1 id="plan-—-list-agency-fr-3-4-1" tabindex="-1">Plan — List Agency (FR 3.4.1) <a class="header-anchor" href="#plan-—-list-agency-fr-3-4-1" aria-label="Permalink to &quot;Plan — List Agency (FR 3.4.1)&quot;">​</a></h1><p>&gt; Liên kết: <a href="./spec.html">spec.md</a> — cho User xem danh sách Agency họ có quyền truy cập (Owner hoặc Member).</p><h2 id="_1-pham-vi-ky-thuat" tabindex="-1">1. Phạm vi kỹ thuật <a class="header-anchor" href="#_1-pham-vi-ky-thuat" aria-label="Permalink to &quot;1. Phạm vi kỹ thuật&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Mục</th><th>Nội dung</th></tr></thead><tbody><tr><td>Repo</td><td><code>brandhub-business-service</code></td></tr><tr><td>File implement</td><td><code>AgencyServiceImpl.listMyAgencies()</code></td></tr><tr><td>File đã có</td><td><code>AgencyController</code> (<code>GET /api/v1/agencies</code>), <code>AgencyRepository</code>, <code>AgencyMemberRepository</code>, <code>AgencyResponse</code></td></tr></tbody></table><h2 id="_2-api-contract-final" tabindex="-1">2. API Contract (final) <a class="header-anchor" href="#_2-api-contract-final" aria-label="Permalink to &quot;2. API Contract (final)&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/agencies</span></span>
<span class="line"><span>Authorization: Bearer &lt;access-token&gt;</span></span>
<span class="line"><span>→ 200 ApiResponse&lt;List&lt;AgencyResponse&gt;&gt;</span></span>
<span class="line"><span>   data = [{ id, name, ownerId, logoUrl, description, status, createdAt, updatedAt }]</span></span></code></pre></div><p>Khác so với spec.md (đề xuất <code>GET /api/v1/agencies</code> trả <code>workspaceCount</code> + <code>createdAt</code>):</p><ul><li><strong>Không có <code>workspaceCount</code></strong> — <code>AgencyResponse</code> chưa có field này (Workspace chưa liên kết <code>agencyId</code>, thuộc DA-E16-10 chưa làm). Bỏ khỏi response hiện tại, bổ sung khi FK <code>Workspace.agency_id</code> xong.</li><li><strong>Trả về cả Agency user làm Member</strong>, không chỉ Owner. Lý do: dashboard user mới đăng ký cần thấy Agency họ được mời vào (khớp luồng accept invitation). Đã ghi nhận lệch với tên FR &quot;Owner-only&quot; trong spec — xem mục 6.</li></ul><h2 id="_3-data-model" tabindex="-1">3. Data Model <a class="header-anchor" href="#_3-data-model" aria-label="Permalink to &quot;3. Data Model&quot;">​</a></h2><ul><li>Đọc <code>agencies</code> qua <code>findByOwnerIdAndStatusNot(userId, SOFT_DELETED)</code> + <code>agency_members</code> qua <code>findByUserId(userId)</code>.</li><li>Gộp 2 tập <code>agencyId</code> (dùng <code>LinkedHashSet</code> giữ thứ tự ổn định), rồi <code>findAllById</code>.</li><li>Filter lần cuối loại <code>SOFT_DELETED</code> (bảo vệ Agency bị soft-delete mà member record còn sót).</li><li><strong>Không migration</strong>.</li></ul><h2 id="_4-luong-xu-ly" tabindex="-1">4. Luồng xử lý <a class="header-anchor" href="#_4-luong-xu-ly" aria-label="Permalink to &quot;4. Luồng xử lý&quot;">​</a></h2><ol><li>Lấy các <code>Agency</code> do user sở hữu, chưa soft-delete.</li><li>Lấy các <code>AgencyMember</code> của user → thêm <code>agencyId</code> vào tập hợp.</li><li><code>findAllById</code> → filter <code>status != SOFT_DELETED</code> → map <code>toResponse</code>.</li></ol><h2 id="_5-dependencies" tabindex="-1">5. Dependencies <a class="header-anchor" href="#_5-dependencies" aria-label="Permalink to &quot;5. Dependencies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Chiều</th><th>Mô tả</th></tr></thead><tbody><tr><td>Chặn bởi</td><td><code>Agency</code>/<code>AgencyMember</code> entity + repository (đã có)</td></tr><tr><td>Bị chặn</td><td><code>View Agency Profile</code> (3.4.4), <code>Update</code> (3.4.5) — cùng repo</td></tr></tbody></table><h2 id="_6-rui-ro-ky-thuat" tabindex="-1">6. Rủi ro kỹ thuật <a class="header-anchor" href="#_6-rui-ro-ky-thuat" aria-label="Permalink to &quot;6. Rủi ro kỹ thuật&quot;">​</a></h2><ul><li><strong>Lệch spec &quot;Owner-only&quot;:</strong> spec ghi Role OWNER và Out-of-Scope &quot;list Agency user chỉ là Member&quot;. Code trả cả owned+member vì luồng mời user cần thấy Agency họ được accept. Cần BA confirm lại nếu muốn giữ đúng Owner-only — chưa chặn, để ghi chú mở.</li><li><strong>Member của Agency bị soft-delete:</strong> <code>findByUserId</code> trả member record mà Agency đã <code>SOFT_DELETED</code> → filter cuối loại bỏ. Đã xử lý ở bước 3.</li></ul>`,16)])])}const g=t(o,[["render",d]]);export{u as __pageData,g as default};
